private int parseEndOfLine(String headerPart, int end) {
    int index = end;
    while (index >= 0) {
        char c = headerPart.charAt(index);
        if (c == '\n') {
            if (index > 0 && headerPart.charAt(index - 1) == '\r') {
                return index - 1;
            }
            return index;
        }
        index--;
    }
    return -1;
}

