public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] typeArguments = parameterizedType.getActualTypeArguments();
    Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];
    for (int i = 0; i < typeArguments.length; i++) {
        Type typeArgument = typeArguments[i];
        if (typeArgument instanceof Class) {
            resolvedArguments[i] = (Class<?>) typeArgument;
        } else if (typeArgument instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) typeArgument;
            String name = typeVariable.getName();
            TypeVariable<?>[] typeParameters = (TypeVariable<?>[]) targetType.getGenericSuperclass() instanceof ParameterizedType
                    ? ((ParameterizedType) targetType.getGenericSuperclass()).getActualTypeArguments()
                    : targetType.getTypeParameters();
            boolean found = false;
            for (TypeVariable<?> typeParameter : targetType.getTypeParameters()) {
                if (typeParameter.getName().equals(name)) {
                    Type actualType = ((ParameterizedType) targetType.getGenericSuperclass()).getActualTypeArguments()[java.util.Arrays.asList(targetType.getTypeParameters()).indexOf(typeParameter)];
                    if (actualType instanceof Class) {
                        resolvedArguments[i] = (Class<?>) actualType;
                        found = true;
                    }
                    break;
                }
            }
            if (!found) {
                return null;
            }
        } else {
            return null;
        }
    }
    return resolvedArguments;
}

