static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        return timeBucket;
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;

    // Convert to a date-like representation to calculate the day of the year
    // We'll use a simple approach: calculate the number of days from the start of the year
    // For simplicity, we'll use a standard calendar calculation

    // Calculate the day of the year
    int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    int yearInt = (int) year;
    int monthInt = (int) month;
    int dayInt = (int) day;

    // Check for leap year
    boolean isLeapYear = (yearInt % 4 == 0 && yearInt % 100 != 0) || (yearInt % 400 == 0);
    if (isLeapYear) {
        daysInMonth[1] = 29;
    }

    int dayOfYear = 0;
    for (int i = 0; i < monthInt - 1; i++) {
        dayOfYear += daysInMonth[i];
    }
    dayOfYear += dayInt;

    // Calculate the bucket start day of the year
    int bucketStartDayOfYear = ((dayOfYear - 1) / dayStep) * dayStep + 1;

    // Convert back to month and day
    int bucketMonth = 1;
    int remainingDays = bucketStartDayOfYear;
    for (int i = 0; i < 12; i++) {
        if (remainingDays <= daysInMonth[i]) {
            bucketMonth = i + 1;
            break;
        }
        remainingDays -= daysInMonth[i];
    }
    int bucketDay = remainingDays;

    // Format back to long
    return year * 10000 + bucketMonth * 100 + bucketDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            size += 1;
        } else if (c < 0x800) {
            size += 2;
        } else if (c < 0xD800 || c > 0xDFFF) {
            size += 3;
        } else {
            // Surrogate pair
            size += 4;
            i++; // skip the low surrogate
        }
    }
    return size;
}

