protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, null, 0, new ArrayList<>());
    }

    // Find a starting vertex
    V start = null;
    for (E edge : tour) {
        start = graph.getEdgeSource(edge);
        break;
    }

    // Build the path by following edges
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();

    V current = start;
    vertices.add(current);

    Set<E> remainingEdges = new HashSet<>(tour);

    while (!remainingEdges.isEmpty()) {
        E nextEdge = null;
        for (E edge : remainingEdges) {
            if (graph.getEdgeSource(edge).equals(current)) {
                nextEdge = edge;
                break;
            }
        }

        if (nextEdge == null) {
            // Try the other direction
            for (E edge : remainingEdges) {
                if (graph.getEdgeTarget(edge).equals(current)) {
                    nextEdge = edge;
                    break;
                }
            }
        }

        if (nextEdge == null) {
            throw new IllegalArgumentException("Cannot form a valid tour from the given edge set");
        }

        edges.add(nextEdge);
        remainingEdges.remove(nextEdge);

        V nextVertex = graph.getEdgeSource(nextEdge).equals(current) ? 
                       graph.getEdgeTarget(nextEdge) : 
                       graph.getEdgeSource(nextEdge);
        vertices.add(nextVertex);
        current = nextVertex;
    }

    // Calculate the total weight
    double weight = 0;
    for (E edge : edges) {
        weight += graph.getEdgeWeight(edge);
    }

    return new GraphPathImpl<>(graph, start, current, weight, vertices, edges);
}

