private String unescapeId(String input) {
    if (input == null || input.isEmpty()) {
        return input;
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < input.length()) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < input.length()) {
            char next = input.charAt(i + 1);
            if (next == 'n') {
                result.append('\n');
                i += 2;
            } else if (next == 't') {
                result.append('\t');
                i += 2;
            } else if (next == 'r') {
                result.append('\r');
                i += 2;
            } else if (next == '\\') {
                result.append('\\');
                i += 2;
            } else if (next == '"') {
                result.append('"');
                i += 2;
            } else if (next == '\'') {
                result.append('\'');
                i += 2;
            } else {
                result.append(c);
                i++;
            }
        } else {
            result.append(c);
            i++;
        }
    }
    return result.toString();
}

