private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == this) {
        return;
    }
    ListNode<E> first = list.first;
    if (first == null) {
        return;
    }
    ListNode<E> last = list.last;
    // Detach from the source list
    list.first = null;
    list.last = null;
    list.size = 0;
    // Attach to this list
    if (this.first == null) {
        this.first = first;
        this.last = last;
    } else {
        last.next = this.first;
        this.first.prev = last;
        this.first = first;
    }
    first.prev = null;
    this.size += list.size;
}

