private void pop(final String descriptor) {
    int count = 0;
    int i = 0;
    while (i < descriptor.length()) {
        char c = descriptor.charAt(i);
        if (c == 'L') {
            int end = descriptor.indexOf(';', i);
            if (end < 0) {
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            count++;
            i = end + 1;
        } else if (c == '[') {
            i++;
        } else if (c == '(') {
            i++;
            while (i < descriptor.length() && descriptor.charAt(i) != ')') {
                char argChar = descriptor.charAt(i);
                if (argChar == 'L') {
                    int end = descriptor.indexOf(';', i);
                    if (end < 0) {
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                    count++;
                    i = end + 1;
                } else if (argChar == '[') {
                    i++;
                } else {
                    if (argChar == 'J' || argChar == 'D') {
                        count += 2;
                    } else {
                        count++;
                    }
                    i++;
                }
            }
            if (i >= descriptor.length()) {
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            i++; // skip ')'
            // After the method descriptor, the return type follows, but we only pop arguments
            // So we stop here
            break;
        } else {
            if (c == 'J' || c == 'D') {
                count += 2;
            } else {
                count++;
            }
            i++;
        }
    }
    for (int j = 0; j < count; j++) {
        outputFrameStack.pop();
