    int count = 0;
    for (Object element : array) {
        if (element != null) {
            count++;
        }
    }
    if (count == array.length) {
        String[] result = new String[array.length];
        for (int i = 0; i < array.length; i++) {
            result[i] = array[i].toString();
        }
        return result;
    }
    String[] result = new String[count];
    int index = 0;
    for (Object element : array) {
        if (element != null) {
            result[index++] = element.toString();
        }
    }
    return result;
}

